style.css:
/* Apply bright yellow theme on dark background to YouTube */
@namespace url(http://www.w3.org/1999/xhtml);
@-moz-document domain("youtube.com") {
/* Background color */
    body {
        background-color: #1A1D23; /* Dark Gray */
        color: #FFFF99; /* Bright Yellow */
        font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; /* Custom Font */
    }

    /* Header and Navigation Bar */
    #masthead-container, #container.ytd-masthead, #guide-button {
        background-color: #2F343A; /* Darker Gray */
        color: #FFFF99; /* Bright Yellow */
    }

    /* Video Titles and Text */
    h1, h2, h3, h4, h5, h6, a, span {
        color: #FFFF99 !important; /* Bright Yellow */
        font-weight: bold;
    }

    /* Sidebar Background */
    #guide {
        background-color: #2F343A; /* Darker Gray */
    }

    /* Buttons and Links */
    .yt-simple-endpoint.style-scope.ytd-button-renderer {
        background-color: #2F343A !important; /* Darker Gray */
        color: #FFFF99 !important; /* Bright Yellow */
        border-radius: 4px;
        padding: 5px;
        border: 1px solid #FFFF99; /* Bright Yellow Border */
    }

    /* Video Player Progress Bar */
    .ytp-progress-bar-container {
        background-color: #2F343A !important; /* Darker Gray */
    }

    .ytp-progress-bar {
        background-color: #FFFF99 !important; /* Bright Yellow */
    }

    /* Highlighted Elements */
    .style-scope.ytd-thumbnail-renderer {
        border: 1px solid #FFFF99; /* Bright Yellow Border */
    }

    /* Hover Effects */
    .style-scope.ytd-thumbnail-renderer:hover {
        background-color: #3B4045; /* Darker Hover Background */
        border: 1px solid #FFFF99; /* Bright Yellow Border */
    }

    /* Additional Brightness */
    .ytd-video-renderer {
        background-color: #333333; /* Slightly Lighter Dark Background */
    }

    .ytd-video-renderer:hover {
        background-color: #444444; /* Hover Background */
    }
}
